
/* ============================================================
   ASTROSPACIAL — APPLICATION SHELL
   Wraps the 8 original single-file modules (unmodified) inside
   a sidebar / topbar SPA shell with simulated auth, command
   palette, and profile menus. Each module runs in its own
   sandboxed iframe (srcdoc) so its original markup/CSS/JS is
   never altered.
   ============================================================ */

/* ---------------- MODULE REGISTRY (base64 payloads of the original files) ---------------- */
const MODULES = {
  "mission-control": "",
  "earth-orbit": "",
  "satellites": "",
  "debris": "",
  "space-stations": "",
  "star-map": "",
  "space-weather": "",
  "collision-monitor": ""
};

const MODULE_META = [
  {id:'mission-control', label:'Mission Control', icon:'◎', group:'CORE', desc:'3D global command view of every tracked object in orbit.'},
  {id:'earth-orbit',     label:'Earth Orbit',      icon:'⊕', group:'CORE', desc:'Orbital shell traffic across altitude layers 200–1000+ km.'},
  {id:'satellites',      label:'Satellites',       icon:'▲', group:'TRACKING', desc:'Search and track active satellites, ISS, GPS, Starlink.'},
  {id:'debris',          label:'Debris',           icon:'✕', group:'TRACKING', desc:'Searchable catalog of tracked orbital debris.'},
  {id:'space-stations',  label:'Space Stations',   icon:'⌂', group:'TRACKING', desc:'ISS, Tiangong and crewed platform status.'},
  {id:'star-map',        label:'Star Map',         icon:'✦', group:'DEEP SPACE', desc:'Interactive star field, constellations and exoplanets.'},
  {id:'space-weather',   label:'Space Weather',    icon:'☀', group:'DEEP SPACE', desc:'Solar wind, flares and geomagnetic activity.'},
  {id:'collision-monitor', label:'Collision Monitor', icon:'⚠', group:'SAFETY', desc:'Conjunction events, closest approaches, risk levels.'},
];

/* ---------------- STATE ---------------- */
const AppState = {
  currentModule: null,
  sidebarCollapsed: false,
};

/* ---------------- MYSQL-BACKED AUTHENTICATION ---------------- */
class AuthManager {
  constructor(){ this.user = null; this.mode = "login"; }
  openModal(mode = this.mode){ this.setMode(mode); document.getElementById("auth-overlay").classList.add("open"); }
  closeModal(){ document.getElementById("auth-overlay").classList.remove("open"); }
  setMode(mode){
    this.mode = mode === "signup" ? "signup" : "login";
    const signup = this.mode === "signup";
    document.getElementById("auth-title").textContent = signup ? "Create your account" : "Welcome back";
    document.getElementById("auth-subtitle").textContent = signup ? "Create a secure account to access your workspace." : "Sign in to your Space Situational Awareness workspace.";
    document.getElementById("auth-name-field").hidden = !signup;
    document.getElementById("auth-confirm-field").hidden = !signup;
    document.getElementById("auth-name").required = signup;
    document.getElementById("auth-confirm-password").required = signup;
    document.getElementById("auth-password").autocomplete = signup ? "new-password" : "current-password";
    document.getElementById("auth-submit").textContent = signup ? "Create account" : "Sign in";
    document.getElementById("auth-switch-copy").innerHTML = signup
      ? `Already have an account? <button type="button" class="auth-switch" onclick="Auth.setMode('login')">Sign in</button>`
      : `New to AstroSpacial? <button type="button" class="auth-switch" onclick="Auth.setMode('signup')">Create an account</button>`;
    this.showMessage("");
  }
  showMessage(message, kind="error"){
    const el = document.getElementById("auth-message");
    el.textContent = message; el.dataset.kind = kind; el.style.display = message ? "block" : "none";
  }
  async request(path, options={}){
    const response = await fetch(`/api/v1${path}`, { credentials:"same-origin", headers:{"Content-Type":"application/json", ...(options.headers||{})}, ...options });
    const payload = await response.json().catch(()=>({error:"Unexpected server response."}));
    if(!response.ok) throw new Error(payload.error || "Request failed.");
    return payload;
  }
  async submit(event){
    event.preventDefault();
    const button = document.getElementById("auth-submit");
    const name = document.getElementById("auth-name").value.trim();
    const email = document.getElementById("auth-email").value.trim();
    const password = document.getElementById("auth-password").value;
    const confirm = document.getElementById("auth-confirm-password").value;
    if(this.mode === "signup" && password !== confirm){ this.showMessage("Passwords do not match."); return; }
    button.disabled = true; button.textContent = this.mode === "signup" ? "Creating account…" : "Signing in…";
    this.showMessage("");
    try {
      const payload = await this.request(this.mode === "signup" ? "/auth/signup" : "/auth/login", {method:"POST", body:JSON.stringify({name,email,password,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC"})});
      this.setUser(payload.user); this.closeModal(); document.getElementById("auth-form").reset();
      Nav.renderAuthAreas(); Toast.show(payload.message || (this.mode === "signup" ? "Account created" : "Signed in"));
    } catch(error){ this.showMessage(error.message); }
    finally { button.disabled = false; button.textContent = this.mode === "signup" ? "Create account" : "Sign in"; }
  }
  setUser(user){ this.user = {...user, initial:(user.name || "M").charAt(0).toUpperCase(), provider:"Email", sub:String(user.id)}; }
  async restoreSession(){
    try { const payload = await this.request("/auth/me"); this.setUser(payload.user); }
    catch { this.user = null; }
    Nav.renderAuthAreas();
  }
  async signInWithEmail(){ document.getElementById("auth-form").requestSubmit(); }
  signInWithGoogle(){ this.showMessage("Google sign-in is not configured. Use your email and password instead."); }
  signInWithClerk(){ this.showMessage("Clerk sign-in is not configured. Use your email and password instead."); }
  async signOut(){
    try { await this.request("/auth/logout", {method:"POST", body:"{}"}); } catch {}
    this.user = null; Nav.renderAuthAreas(); Menus.closeAll(); Modal.close(); Toast.show("Signed out");
  }
  openProfileModal(){
    if(!this.user){ this.openModal(); return; }
    const u=this.user;
    Modal.open(`<button class="modal-close" onclick="Modal.close()">✕</button><div class="profile-avatar-lg">${u.initial}</div><h2 class="modal-title" style="text-align:center">Your profile</h2><p class="modal-sub" style="text-align:center">Details saved to your account.</p><div class="modal-section"><h4>ACCOUNT</h4><div class="profile-meta-row"><span>Email</span><span>${u.email}</span></div><div class="profile-meta-row"><span>Account ID</span><span>${u.id}</span></div></div><div class="modal-section"><h4>YOUR DETAILS</h4><div class="auth-field"><label>DISPLAY NAME</label><input type="text" id="pf-name" value="${String(u.name).replace(/&/g,"&amp;").replace(/"/g,"&quot;")}"></div><div class="auth-field"><label>ROLE / TITLE</label><input type="text" id="pf-role" value="${String(u.role || "").replace(/&/g,"&amp;").replace(/"/g,"&quot;")}" placeholder="e.g. Orbital Analyst"></div><div class="auth-field"><label>TIMEZONE</label><input type="text" id="pf-tz" value="${String(u.timezone || "UTC").replace(/&/g,"&amp;").replace(/"/g,"&quot;")}"></div></div><div class="modal-footer"><button class="btn" onclick="Modal.close()">Cancel</button><button class="btn btn-primary" onclick="Auth.saveProfile()">Save changes</button></div>`);
  }
  async saveProfile(){
    const name=document.getElementById("pf-name").value.trim(), role=document.getElementById("pf-role").value.trim(), timezone=document.getElementById("pf-tz").value.trim();
    try { const payload=await this.request("/auth/me",{method:"PATCH",body:JSON.stringify({name,role,timezone})}); this.setUser(payload.user); Nav.renderAuthAreas(); Modal.close(); Toast.show("Profile updated"); }
    catch(error){ Toast.show(error.message); }
  }
}
const Auth = new AuthManager();
document.getElementById("auth-form").addEventListener("submit", event => Auth.submit(event));

/* ---------------- TOASTS ---------------- */
class ToastManager{
  show(msg){
    const stack = document.getElementById('toast-stack');
    const el = document.createElement('div');
    el.className = 'toast';
    el.innerHTML = '<span class="tdot"></span>' + msg;
    stack.appendChild(el);
    setTimeout(()=>{ el.style.opacity='0'; el.style.transition='.3s'; setTimeout(()=>el.remove(),300); }, 3200);
  }
}
const Toast = new ToastManager();

/* ---------------- GENERIC MODAL (Settings / Profile / Watchlist share this) ---------------- */
class ModalHelper{
  open(html){
    document.getElementById('generic-modal-box').innerHTML = html;
    document.getElementById('generic-overlay').classList.add('open');
  }
  close(){
    document.getElementById('generic-overlay').classList.remove('open');
  }
}
const Modal = new ModalHelper();
document.getElementById('generic-overlay').addEventListener('click', (e)=>{
  if(e.target.id === 'generic-overlay') Modal.close();
});

/* ---------------- SETTINGS (functional, persisted, applied live) ---------------- */
class SettingsManager{
  constructor(){
    this.defaults = {performance:'auto', reducedMotion:false, highContrast:false, largeText:false, animations:true, homeLiveStats:true};
    this.data = {...this.defaults, ...JSON.parse(localStorage.getItem('oe_settings') || '{}')};
    this.apply();
  }
  save(){ localStorage.setItem('oe_settings', JSON.stringify(this.data)); }
  apply(){
    document.body.classList.toggle('reduced-motion', this.data.reducedMotion || !this.data.animations);
    document.body.classList.toggle('high-contrast', this.data.highContrast);
    document.body.classList.toggle('large-text', this.data.largeText);
  }
  set(key, value){
    this.data[key] = value;
    this.save();
    this.apply();
    this.render();
  }
  toggle(key){ this.set(key, !this.data[key]); }
  open(){ this.render(); }
  render(){
    const d = this.data;
    Modal.open(`
      <button class="modal-close" onclick="Modal.close()">✕</button>
      <div class="modal-title">Settings</div>
      <p class="modal-sub">Applied instantly and saved to this browser only.</p>

      <div class="modal-section">
        <h4>PERFORMANCE MODE</h4>
        <div class="pill-row">
          ${['low','medium','high','auto'].map(p=>`
            <button class="pill ${d.performance===p?'active':''}" onclick="Settings.set('performance','${p}')">${p.toUpperCase()}</button>
          `).join('')}
        </div>
      </div>

      <div class="modal-section">
        <h4>DISPLAY</h4>
        <div class="toggle-row">
          <div class="tr-label"><span>Interface animations</span><span class="tr-sub">Pulses, transitions, starfield motion</span></div>
          <div class="switch ${d.animations?'on':''}" onclick="Settings.toggle('animations')"></div>
        </div>
        <div class="toggle-row">
          <div class="tr-label"><span>Live homepage stats</span><span class="tr-sub">Ticking object counters on Home</span></div>
          <div class="switch ${d.homeLiveStats?'on':''}" onclick="Settings.toggle('homeLiveStats')"></div>
        </div>
      </div>

      <div class="modal-section">
        <h4>ACCESSIBILITY</h4>
        <div class="toggle-row">
          <div class="tr-label"><span>Reduced motion</span><span class="tr-sub">Disable all non-essential animation</span></div>
          <div class="switch ${d.reducedMotion?'on':''}" onclick="Settings.toggle('reducedMotion')"></div>
        </div>
        <div class="toggle-row">
          <div class="tr-label"><span>High contrast</span><span class="tr-sub">Brighter grays and borders</span></div>
          <div class="switch ${d.highContrast?'on':''}" onclick="Settings.toggle('highContrast')"></div>
        </div>
        <div class="toggle-row">
          <div class="tr-label"><span>Larger text</span><span class="tr-sub">Increase base font size</span></div>
          <div class="switch ${d.largeText?'on':''}" onclick="Settings.toggle('largeText')"></div>
        </div>
      </div>

      <div class="modal-footer">
        <button class="btn" onclick="Settings.reset()">Reset to defaults</button>
        <button class="btn btn-primary" onclick="Modal.close()">Done</button>
      </div>
    `);
  }
  reset(){
    this.data = {...this.defaults};
    this.save();
    this.apply();
    this.render();
    Toast.show('Settings reset to defaults');
  }
}
const Settings = new SettingsManager();

/* ---------------- WATCHLIST (functional, persisted) ---------------- */
class WatchlistManager{
  list(){ return JSON.parse(localStorage.getItem('oe_watchlist') || '[]'); }
  save(items){ localStorage.setItem('oe_watchlist', JSON.stringify(items)); }
  add(moduleId){
    const meta = MODULE_META.find(m=>m.id===moduleId);
    if(!meta) return;
    const items = this.list();
    if(items.some(i=>i.id===moduleId)){
      Toast.show(meta.label + ' is already on your watchlist');
      return;
    }
    items.push({id:meta.id, label:meta.label, icon:meta.icon, addedAt:new Date().toISOString()});
    this.save(items);
    Nav.renderSidebarBottom();
    Toast.show(meta.label + ' added to watchlist');
  }
  remove(moduleId){
    const items = this.list().filter(i=>i.id!==moduleId);
    this.save(items);
    Nav.renderSidebarBottom();
    this.render();
    Toast.show('Removed from watchlist');
  }
  open(){ this.render(); }

  /* ---- Objects watchlisted from inside the Mission Control module (synced via postMessage) ---- */
  listObjects(){ return JSON.parse(localStorage.getItem('oe_watchlist_objects') || '[]'); }
  saveObjects(items){ localStorage.setItem('oe_watchlist_objects', JSON.stringify(items)); }
  addObject(obj){
    if(!obj || !obj.id) return;
    const items = this.listObjects();
    if(items.some(i=>i.id===obj.id)) return;
    items.push({...obj, addedAt:new Date().toISOString()});
    this.saveObjects(items);
    Nav.renderSidebarBottom();
    if(document.getElementById('generic-overlay').classList.contains('open')) this.render();
  }
  removeObject(objId){
    const items = this.listObjects().filter(i=>i.id!==objId);
    this.saveObjects(items);
    Nav.renderSidebarBottom();
    this.render();
    this.syncFrame();
  }
  syncFrame(){
    const frame = document.getElementById('content-frame');
    if(frame && frame.contentWindow){
      frame.contentWindow.postMessage({type:'oe-watchlist-sync', ids:this.listObjects().map(i=>i.id)}, '*');
    }
  }

  render(){
    const items = this.list();
    const objItems = this.listObjects();
    Modal.open(`
      <button class="modal-close" onclick="Modal.close()">✕</button>
      <div class="modal-title">Watchlist</div>
      <p class="modal-sub">Modules and tracked objects you're keeping an eye on. Stored locally in this browser.</p>
      <div class="modal-section" style="margin-bottom:6px;">
        <h4>MODULES</h4>
        ${items.length ? items.map(i=>`
          <div class="wl-item">
            <div class="wl-meta">
              <span>${i.icon} ${i.label}</span>
              <span class="wl-time">Added ${new Date(i.addedAt).toLocaleString()}</span>
            </div>
            <div class="wl-item-actions">
              <button onclick="Router.open('${i.id}'); Modal.close();">Open</button>
              <button onclick="Watchlist.remove('${i.id}')">Remove</button>
            </div>
          </div>
        `).join('') : '<div class="wl-empty">Nothing on your watchlist yet.<br>Use the ⋯ menu on any sidebar module to add one.</div>'}
      </div>
      <div class="modal-section" style="margin-bottom:6px;">
        <h4>TRACKED OBJECTS (FROM MISSION CONTROL)</h4>
        ${objItems.length ? objItems.map(i=>`
          <div class="wl-item">
            <div class="wl-meta">
              <span>☆ ${i.name}</span>
              <span class="wl-time">${i.objType || ''}${i.altitude ? ' · ' + i.altitude + ' KM' : ''} · Added ${new Date(i.addedAt).toLocaleString()}</span>
            </div>
            <div class="wl-item-actions">
              <button onclick="Router.open('mission-control'); Modal.close();">Open</button>
              <button onclick="Watchlist.removeObject('${i.id}')">Remove</button>
            </div>
          </div>
        `).join('') : '<div class="wl-empty">No objects tracked yet.<br>Select an object in Mission Control and click + WATCHLIST.</div>'}
      </div>
      <div class="modal-footer">
        <button class="btn btn-primary" onclick="Modal.close()">Close</button>
      </div>
    `);
  }
}
const Watchlist = new WatchlistManager();

/* Receive watchlist add/remove/sync-request messages from the Mission Control iframe */
window.addEventListener('message', (e)=>{
  const d = e.data;
  if(!d || typeof d !== 'object') return;
  if(d.type === 'oe-watch-add'){
    Watchlist.addObject(d.obj);
  } else if(d.type === 'oe-watch-remove'){
    Watchlist.removeObject(d.id);
  } else if(d.type === 'oe-watch-request-sync'){
    Watchlist.syncFrame();
  }
});

/* ---------------- MENUS (dropdown / 3-dot popovers) ---------------- */
class MenuManager{
  closeAll(){
    document.getElementById('profile-dropdown').classList.remove('open');
    document.getElementById('sb-item-menu').classList.remove('open');
  }
  openAt(el, anchorEl){
    this.closeAll();
    const r = anchorEl.getBoundingClientRect();
    el.style.top = (r.bottom + 6) + 'px';
    el.style.left = Math.min(r.left, window.innerWidth - 230) + 'px';
    el.classList.add('open');
  }
}
const Menus = new MenuManager();
document.addEventListener('click', (e)=>{
  if(!e.target.closest('.dropdown') && !e.target.closest('.profile-btn') &&
     !e.target.closest('.sb-item-menu') && !e.target.closest('.sb-dots')){
    Menus.closeAll();
  }
});

/* ---------------- SIDEBAR ---------------- */
class SidebarManager{
  toggleCollapse(){
    AppState.sidebarCollapsed = !AppState.sidebarCollapsed;
    document.getElementById('sidebar').classList.toggle('collapsed', AppState.sidebarCollapsed);
    document.getElementById('sb-collapse-btn').textContent = AppState.sidebarCollapsed ? '»' : '«';
  }
  toggleMobile(){
    document.getElementById('sidebar').classList.toggle('mobile-open');
  }
  openItemMenu(moduleId, anchorEl){
    const menu = document.getElementById('sb-item-menu');
    menu.innerHTML = `
      <button onclick="Router.open('${moduleId}'); Menus.closeAll();">↗ Open module</button>
      <button onclick="window.open(Router.buildBlobUrl('${moduleId}'),'_blank'); Menus.closeAll();">⧉ Open in new tab</button>
      <button onclick="Watchlist.add('${moduleId}'); Menus.closeAll();">☆ Add to watchlist</button>
    `;
    Menus.openAt(menu, anchorEl);
  }
}
const Sidebar = new SidebarManager();

/* ---------------- NAV / RENDERING ---------------- */
class NavManager{
  renderSidebar(){
    const nav = document.getElementById('sb-nav');
    let html = `
      <div class="sb-section-label">GENERAL</div>
      <div class="sb-item" id="sb-item-home" onclick="Router.goHome()">
        <span class="ic">⌂</span>
        <span class="label">Home</span>
      </div>`;
    let lastGroup = null;
    MODULE_META.forEach(m=>{
      if(m.group !== lastGroup){
        html += `<div class="sb-section-label">${m.group}</div>`;
        lastGroup = m.group;
      }
      html += `
        <div class="sb-item" id="sb-item-${m.id}" onclick="Router.open('${m.id}')">
          <span class="ic">${m.icon}</span>
          <span class="label">${m.label}</span>
          <span class="sb-dots" onclick="event.stopPropagation(); Sidebar.openItemMenu('${m.id}', this)">⋯</span>
        </div>`;
    });
    nav.innerHTML = html;
    this.renderSidebarBottom();
  }
  renderSidebarBottom(){
    const wlCount = Watchlist.list().length + Watchlist.listObjects().length;
    document.getElementById('sidebar-bottom').innerHTML = `
      <div class="sb-item" onclick="Toast.show('No new alerts')"><span class="ic">⏰</span><span class="label">Alerts</span></div>
      <div class="sb-item" onclick="Watchlist.open()"><span class="ic">☆</span><span class="label">Watchlist</span>${wlCount ? `<span class="sb-badge-count">${wlCount}</span>` : ''}</div>
      <div class="sb-item" onclick="Settings.open()"><span class="ic">⚙</span><span class="label">Settings</span></div>
    `;
  }
  setActive(id){
    document.querySelectorAll('.sb-item').forEach(el=>el.classList.remove('active'));
    const el = document.getElementById('sb-item-'+id);
    if(el) el.classList.add('active');
    const meta = MODULE_META.find(m=>m.id===id);
    document.getElementById('tb-title').textContent = meta ? meta.label : id;
  }
  filterModules(query){
    query = query.trim().toLowerCase();
    document.querySelectorAll('.ql-card').forEach(card=>{
      const match = card.dataset.search.includes(query);
      card.style.display = match ? '' : 'none';
    });
  }
  renderAuthAreas(){
    const home = document.getElementById('home-auth-area');
    const profileArea = document.getElementById('profile-area');
    if(Auth.user){
      home.innerHTML = `<button class="btn btn-sm" onclick="Router.enterMissionControl()">Dashboard</button>`;
      profileArea.innerHTML = `
        <button class="profile-btn" onclick="Nav.toggleProfileMenu(this)">
          <span class="avatar">${Auth.user.initial}</span>
          <span class="profile-name">${Auth.user.name}</span>
        </button>`;
    } else {
      home.innerHTML = `<button class="btn btn-sm" onclick="Auth.openModal()">Sign In</button>`;
      profileArea.innerHTML = `<button class="btn btn-sm" onclick="Auth.openModal()">Sign In</button>`;
    }
  }
  toggleProfileMenu(anchorEl){
    const dd = document.getElementById('profile-dropdown');
    if(dd.classList.contains('open')){ Menus.closeAll(); return; }
    dd.innerHTML = `
      <div class="dropdown-header">
        <div class="dn">${Auth.user.name}</div>
        <div class="de">${Auth.user.email} · · account</div>
      </div>
      <button onclick="Auth.openProfileModal(); Menus.closeAll();">◍ Profile</button>
      <button onclick="Settings.open(); Menus.closeAll();">⚙ Settings</button>
      <button onclick="Router.goHome(); Menus.closeAll();">⌂ Home</button>
      <hr>
      <button class="danger" onclick="Auth.signOut();">⏻ Sign out</button>
    `;
    Menus.openAt(dd, anchorEl);
  }
  renderHomeExtras(){
    // Resume-session card (reactive to last visited module)
    const lastId = localStorage.getItem('oe_last_module');
    const wrap = document.getElementById('resume-card-wrap');
    const meta = lastId ? MODULE_META.find(m=>m.id===lastId) : null;
    if(meta){
      wrap.innerHTML = `
        <div class="resume-card">
          <div class="rc-left">
            <div class="rc-icon">${meta.icon}</div>
            <div>
              <div class="rc-title">CONTINUE WHERE YOU LEFT OFF</div>
              <div class="rc-name">${meta.label}</div>
            </div>
          </div>
          <button class="btn btn-primary btn-sm" onclick="Router.open('${meta.id}')">Resume →</button>
        </div>`;
    } else {
      wrap.innerHTML = '';
    }

    const ql = document.getElementById('ql-grid');
    ql.innerHTML = MODULE_META.map(m=>`
      <button class="ql-card" data-search="${(m.label+' '+m.desc+' '+m.group).toLowerCase()}" onclick="Router.open('${m.id}')">
        <div class="icon">${m.icon}</div>
        <h3>${m.label}</h3>
        <p>${m.desc}</p>
        <span class="tag">${m.group}</span>
      </button>
    `).join('');

    this.startLiveStats();
  }
  startLiveStats(){
    if(this._liveStatsStarted) return;
    this._liveStatsStarted = true;
    this._baseStats = {objects:9421, debris:22381, stations:17, neos:2431};
    const render = ()=>{
      const s = this._baseStats;
      const stats = document.getElementById('home-stats');
      if(!stats) return;
      stats.innerHTML = `
        <div class="home-stat live"><div class="num">${s.objects.toLocaleString()}</div><div class="lbl">LIVE OBJECTS</div></div>
        <div class="home-stat live"><div class="num">${s.debris.toLocaleString()}</div><div class="lbl">TRACKED DEBRIS</div></div>
        <div class="home-stat live"><div class="num">${s.stations}</div><div class="lbl">SPACE STATIONS</div></div>
        <div class="home-stat live"><div class="num">${s.neos.toLocaleString()}</div><div class="lbl">NEAR-EARTH OBJECTS</div></div>
      `;
    };
    render();
    setInterval(()=>{
      if(!Settings.data.homeLiveStats) return;
      const s = this._baseStats;
      s.objects += Math.round((Math.random()-0.4)*4);
      s.debris += Math.round((Math.random()-0.3)*6);
      s.neos += Math.random() > 0.7 ? (Math.random()>0.5?1:-1) : 0;
      render();
    }, 3500);
  }
}
const Nav = new NavManager();

/* ---------------- ROUTER (iframe module loader) ---------------- */
class RouterManager{
  goHome(){
    document.getElementById('home-view').style.display = 'flex';
    document.getElementById('dashboard-view').style.display = 'none';
    document.querySelectorAll('.sb-item').forEach(el=>el.classList.remove('active'));
    Nav.renderHomeExtras();
  }
  enterMissionControl(){ this.open('mission-control'); }
  buildBlobUrl(id){
    const b64 = MODULES[id];
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
    const blob = new Blob([bytes], {type:'text/html'});
    return URL.createObjectURL(blob);
  }
  open(id){
    if(!MODULES[id]){ Toast.show('Module not available'); return; }
    document.getElementById('home-view').style.display = 'none';
    document.getElementById('dashboard-view').style.display = 'block';
    document.getElementById('sidebar').classList.remove('mobile-open');
    AppState.currentModule = id;
    localStorage.setItem('oe_last_module', id);
    Nav.setActive(id);

    const frame = document.getElementById('content-frame');
    const loading = document.getElementById('frame-loading');
    loading.style.display = 'flex';
    frame.style.opacity = '0';

    const bin = atob(MODULES[id]);
    frame.srcdoc = bin;
    frame.onload = ()=>{
      loading.style.display = 'none';
      frame.style.opacity = '1';
      if(id === 'mission-control') Watchlist.syncFrame();
    };
  }
}
const Router = new RouterManager();

/* ---------------- COMMAND PALETTE ---------------- */
class CommandPalette{
  constructor(){
    this.items = [
      ...MODULE_META.map(m=>({label:'Open '+m.label, icon:m.icon, action:()=>Router.open(m.id)})),
      {label:'Go to Home', icon:'⌂', action:()=>Router.goHome()},
      {label:'Open Watchlist', icon:'☆', action:()=>Watchlist.open()},
      {label:'Open Settings', icon:'⚙', action:()=>Settings.open()},
      {label:'Sign in / Profile', icon:'◍', action:()=>Auth.user?Auth.openProfileModal():Auth.openModal()},
    ];
    this.selected = 0;
  }
  open(){
    document.getElementById('cmdk-overlay').classList.add('open');
    const input = document.getElementById('cmdk-input');
    input.value=''; input.focus();
    this.filter('');
  }
  close(){ document.getElementById('cmdk-overlay').classList.remove('open'); }
  filter(q){
    q = q.toLowerCase();
    this.filtered = this.items.filter(i=>i.label.toLowerCase().includes(q));
    this.selected = 0;
    this.render();
  }
  render(){
    const list = document.getElementById('cmdk-list');
    list.innerHTML = this.filtered.map((it,idx)=>`
      <div class="cmdk-item ${idx===this.selected?'sel':''}" onclick="CmdK.choose(${idx})">
        <span class="ic">${it.icon}</span><span>${it.label}</span>
      </div>`).join('') || '<div class="cmdk-item">No results</div>';
  }
  move(delta){
    if(!this.filtered.length) return;
    this.selected = (this.selected + delta + this.filtered.length) % this.filtered.length;
    this.render();
  }
  choose(idx){
    const it = this.filtered[idx !== undefined ? idx : this.selected];
    if(it){ it.action(); this.close(); }
  }
}
const CmdK = new CommandPalette();

document.addEventListener('keydown', (e)=>{
  if((e.metaKey || e.ctrlKey) && e.key.toLowerCase()==='k'){
    e.preventDefault(); CmdK.open();
  } else if(e.key === '/' && document.activeElement.tagName !== 'INPUT'){
    e.preventDefault(); CmdK.open();
  } else if(e.key === 'Escape'){
    CmdK.close(); Auth.closeModal(); Menus.closeAll(); Modal.close();
  } else if(document.getElementById('cmdk-overlay').classList.contains('open')){
    if(e.key==='ArrowDown'){ e.preventDefault(); CmdK.move(1); }
    if(e.key==='ArrowUp'){ e.preventDefault(); CmdK.move(-1); }
    if(e.key==='Enter'){ e.preventDefault(); CmdK.choose(); }
  }
});
document.getElementById('cmdk-overlay').addEventListener('click', (e)=>{
  if(e.target.id === 'cmdk-overlay') CmdK.close();
});
document.getElementById('auth-overlay').addEventListener('click', (e)=>{
  if(e.target.id === 'auth-overlay') Auth.closeModal();
});

/* ---------------- STARFIELD (home backdrop) ---------------- */
(function(){
  const canvas = document.getElementById('star-canvas');
  const ctx = canvas.getContext('2d');
  let stars = [];
  function resize(){
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    stars = Array.from({length: 260}, ()=>({
      x: Math.random()*canvas.width,
      y: Math.random()*canvas.height,
      r: Math.random()*1.3 + 0.2,
      a: Math.random()*0.6 + 0.2,
      s: Math.random()*0.02
    }));
  }
  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    ctx.fillStyle = '#fff';
    stars.forEach(st=>{
      st.a += st.s;
      const alpha = 0.3 + Math.abs(Math.sin(st.a))*0.5;
      ctx.globalAlpha = alpha;
      ctx.beginPath();
      ctx.arc(st.x, st.y, st.r, 0, Math.PI*2);
      ctx.fill();
    });
    ctx.globalAlpha = 1;
    requestAnimationFrame(draw);
  }
  window.addEventListener('resize', resize);
  resize(); draw();
})();

